record ErrorBody(Instant timestamp,int status,String code,String message,String path){} @RestControllerAdvice class Errors{@ExceptionHandler(Err.class)ResponseEntity<ErrorBody>err(Err e,org.springframework.web.context.request.ServletWebRequest r){return ResponseEntity.status(e.status).body(new ErrorBody(Instant.now(),e.status,e.status==409?"CONFLICT":e.status==404?"NOT_FOUND":"VALIDATION_ERROR",e.getMessage(),r.getRequest().getRequestURI()));}@ExceptionHandler(Exception.class)ResponseEntity<ErrorBody>other(Exception e,org.springframework.web.context.request.ServletWebRequest r){int s=e instanceof org.springframework.web.bind.MethodArgumentNotValidException||e instanceof org.springframework.http.converter.HttpMessageNotReadableException?400:500;return ResponseEntity.status(s).body(new ErrorBody(Instant.now(),s,s==400?"VALIDATION_ERROR":"INTERNAL_ERROR",s==400?"Invalid request":"Request failed",r.getRequest().getRequestURI()));}}class Err extends RuntimeException{int status;Err(int s,String m){super(m);status=s;}}
